impl markup::Transform for super::AGuide {
    fn transform(&self, ctx: &mut dyn markup::Context) -> Self {
        let node = markup::ask(ctx.presentation(), super::Context::a_guide, self);
        node.unwrap_or_else(|| self.transform_children(ctx))
    }

    fn transform_children(&self, ctx: &mut dyn markup::Context) -> Self {
        Self {
            orient: self.orient.clone(),
            pos: self.pos.clone(),
            unknown: markup::transform_unknown(&self.unknown, ctx, &markup::Rebase::default()),
        }
    }
}

impl markup::Visit for super::AGuide {
    fn visit(&self, visitor: &mut dyn markup::Visitor) {
        let next = markup::show(visitor.presentation(), super::Visitor::a_guide, self);
        if next == markup::Descend::Yes {
            self.visit_children(visitor);
        }
    }

    fn visit_children(&self, visitor: &mut dyn markup::Visitor) {
        markup::Walk::new(&self.unknown).finish(visitor);
    }
}

impl WriteThrough for super::AGuide {
    fn write_children_through(
        &self,
        ctx: &mut dyn markup::Context,
        out: &mut PartWriter<'_>,
    ) -> io::Result<()> {
        let mut through = markup::Through::new(out, &super::A_GUIDE_SHAPE, &self.unknown);
        through.attribute(0, &self.orient);
        through.attribute(1, &self.pos);
        through.finish(ctx)
    }

    fn write_through(
        &self,
        ctx: &mut dyn markup::Context,
        out: &mut PartWriter<'_>,
    ) -> io::Result<()> {
        let written =
            markup::ask_write(ctx.presentation(), super::Context::write_a_guide, self, out)?;
        if written == Written::Yes {
            return Ok(());
        }
        let replaced = markup::ask(ctx.presentation(), super::Context::a_guide, self);
        if let Some(node) = replaced {
            return node.write_children_through(&mut Unchanged, out);
        }
        self.write_children_through(ctx, out)
    }
}

